Method Request → Response Least role Notes ListContentScenarios ListContentScenariosRequest → ListContentScenariosResponse viewer ListContentScenarios returns the scenarios of a run ("" = the caller’s latest run that has them), best first, withheld ones last. No model call. GetResearchTuning GetResearchTuningRequest → ResearchTuning viewer GetResearchTuning returns what the caller saved, and what the latest audit found to seed it with (people it sells to, what it sells). SaveResearchTuning SaveResearchTuningRequest → ResearchTuning editor SaveResearchTuning stores the caller’s tuning (per account; an agency client is its own account). The next audit and every re-tune use it. RetuneContentScenarios RetuneContentScenariosRequest → RetuneContentScenariosResponse editor RetuneContentScenarios re-runs the scenarios of a finished run with the saved tuning, detached; ListContentScenarios shows the result. // One post idea of a scenario. message ScenarioItem { string hook = 1; // the first line people see string format = 2; // instagram_feed | instagram_carousel | instagram_reel | instagram_story | youtube_long | youtube_shorts string cta = 3; // what the post asks people to do, in plain words string why = 4; // why it matters to this person string channel = 5; // instagram | youtube } // One finding a scenario is drawn from. message ScenarioEvidence { string ref = 1; // "E3" string kind = 2; // site | offering | niche | trend | trending_post | competitor_channel | lead | persona | gap string text = 3; string source_url = 4; // "" when the finding has no page of its own } // One scenario. Contract with the campaign plan generator (Agent D): it reads // the kept scenarios (withheld = false) and their items when present. message ContentScenario { string id = 1; string audit_run_id = 2; string persona = 3; // who it is for (from the tuning, the audit's leads or its audience) string pain = 4; // the problem or job that person has string angle = 5; // educate | proof | behind_the_scenes | offer | event string offering = 6; // what the business sells that it serves (stated on the site or by the owner) repeated string channel_formats = 7; repeated string evidence_refs = 8; // refs into evidence double score = 9; // 0-100: evidence strength and fit; ranks the list bool withheld = 10; string withheld_reason = 11; repeated ScenarioItem items = 12; repeated ScenarioEvidence evidence = 13; // How the score was reached, in plain words ("3 findings, 2 measured; …"). string score_basis = 14; // The plan gate's verdict: concur | unable | off ("" when withheld before it). string verdict = 15; // persona_source: tuning | leads | audience. offering_source: tuning | site. string persona_source = 16; string offering_source = 17; // What PULSE's own web research found for it ("" = none ran or none found). string research_note = 18; // The Go checks' summary ("scenario-items 100/pass"). repeated string checks = 19; } // One day of the Instagram week (daily posting across several scenarios): // no topic twice in a row, at most one offer post in any four. message RotationSlot { int32 day = 1; // 1..7 string scenario_id = 2; int32 item_index = 3; // into that scenario's items string format = 4; string angle = 5; string topic = 6; // the scenario's pain, for the rotation rule bool promo = 7; // angle == offer } message ListContentScenariosRequest { string audit_run_id = 1; // "" = the latest run with scenarios } message ListContentScenariosResponse { string audit_run_id = 1; string domain = 2; // The run's content_scenarios stage: pending | running | done | failed | // skipped ("" = no run), and its detail or error. string stage_status = 3; string stage_detail = 4; repeated ContentScenario scenarios = 5; // Derived from the measured inputs; run inside the time budget; not run // because the budget could not pay for them (they are listed withheld). int32 derived = 6; int32 dispatched = 7; int32 capped = 8; string depth = 9; // quick | deep repeated RotationSlot instagram_rotation = 10; string generated_at = 11; // RFC 3339; "" = none yet // The tuning the scenarios were built with. ResearchTuning tuning = 12; // Why there is no Instagram week ("" = there is one). string rotation_note = 13; // The hash-chain head over every scenario's outcome (runi/chain). string trace_head = 14; } // What the person tunes the research with. Lists are plain words; an empty // list or a 0 count means "not set", never "none". message ResearchTuning { string goal = 1; repeated string personas = 2; // who they sell to repeated string offerings = 3; // what they sell repeated string channels = 4; // instagram | youtube int32 posts_per_week = 5; // 0 = not set int32 stories_per_day = 6; // 0 = not set repeated string focus_topics = 7; repeated string avoid_topics = 8; string language = 9; string region = 10; string depth = 11; // quick | deep ("" = quick) string updated_at = 12; // "" = never saved bool saved = 13; // false: nothing saved yet (the seeds below still apply) // What the latest audit found, offered as chips: never saved by itself. repeated string seeded_personas = 14; repeated string seeded_offerings = 15; } message GetResearchTuningRequest {} message SaveResearchTuningRequest { ResearchTuning tuning = 1; } message RetuneContentScenariosRequest { string audit_run_id = 1; // "" = the latest run } message RetuneContentScenariosResponse { string audit_run_id = 1; string status = 2; // started | running (already re-tuning) string detail = 3; }

