Method Request → Response Least role Notes CreateDiagnostic CreateDiagnosticRequest → Diagnostic editor CreateDiagnostic creates a new diagnostic record from user-provided business info. GetDiagnostic GetDiagnosticRequest → Diagnostic viewer GetDiagnostic fetches a single diagnostic by ID. ListDiagnostics ListDiagnosticsRequest → ListDiagnosticsResponse viewer ListDiagnostics returns paginated diagnostics for the current user/org. GenerateDiagnostic GenerateDiagnosticRequest → stream StreamChunk editor GenerateDiagnostic streams AI-generated diagnostic analysis in real-time. UpdateDiagnostic UpdateDiagnosticRequest → Diagnostic editor UpdateDiagnostic updates a diagnostic’s metadata or user notes. ExportDiagnosticPDF ExportDiagnosticPDFRequest → ExportDiagnosticPDFResponse viewer ExportDiagnosticPDF generates a branded PDF export of the diagnostic. ApplyAuditActions ApplyAuditActionsRequest → ApplyAuditActionsResponse editor AuditURL was removed: a site score is AuditPipelineService.RunAudit with score_only set, and the report is AuditRun.score_report. ApplyAuditActions audits a URL and maps the auto-applyable fix-artifacts into a server-local repository (stack-aware, idempotent). mode escalates from “plan” (dry-run, default, no side effects) to “apply”/“commit”/“pr”. Copy/infra actions are returned as manual for human review, never applied. Also uses StreamChunk, PaginationRequest, PaginationResponse, AssistantToolEvent, AssistantProposal, Channel.
// ContentSuggestion is one concrete content idea within a ChannelPrescription. message ContentSuggestion { string title = 1; string description = 2; string cta = 3; } // ChannelPrescription is the AI's structured recommendation for a single // channel — role in the overall strategy, priority, concrete content ideas, // preferred CTA style, and the KPIs that matter for it. message ChannelPrescription { Channel channel = 1; string role = 2; string priority = 3; repeated ContentSuggestion suggestions = 4; string cta_recommendation = 5; repeated string kpis = 6; // The judging ladder's verdict on this prescription (cmd/judgement_gate.go). // Only concur and unable-to-judge ever appear here: a dissented // prescription is withheld and lives only in Diagnostic.judgements. // Unset = judging was off (PULSE_JUDGEMENT=off) or it predates the gate. runink.ui.judgement.v1.Judgement judgement = 7; } // DocumentPrescription is the AI's structured recommendation for a single // document format — its role, priority, and concrete ideas. message DocumentPrescription { string format = 1; string role = 2; string priority = 3; repeated ContentSuggestion suggestions = 4; } // BrandVisibilityInsight is a Generative-Engine-Optimization finding: how to // shape the brand's lexical/semantic presence so generative-AI metasearch // engines (AI Overviews, Perplexity, ChatGPT, etc.) recognise, surface, and // cite the company in context — a distinct insight stream from the // audience-targeting prescriptions above. message BrandVisibilityInsight { // entity_authority | semantic_topics | answer_framing | lexical_relevance | // structured_data | authority_sources string dimension = 1; string insight = 2; // what the diagnosis found about current AI-search visibility repeated string target_terms = 3; // entities/phrases/queries to own for AI-search lexical relevance repeated string actions = 4; // concrete actions to raise generative-AI discoverability string rationale = 5; // why this shapes brand awareness in AI/metasearch engines // The judging ladder's verdict on this insight; see ChannelPrescription.judgement. runink.ui.judgement.v1.Judgement judgement = 6; } // AudienceSegment is one tier of a 360-degree audience map (e.g. decision // makers, influencers, end users), with the areas/roles/technologies that // define it. message AudienceSegment { string level = 1; repeated string areas = 2; repeated string roles = 3; repeated string technologies = 4; } // CronogramTask is one task in the multichannel execution calendar. message CronogramTask { int32 week = 1; Channel channel = 2; string task = 3; bool completed = 4; } // Diagnostic is a full multichannel business diagnostic report. message Diagnostic { string id = 1; string user_id = 2; string business_name = 3; string industry = 4; string niche = 5; string target_audience = 6; string current_channels = 7; // comma-separated active channels string competitors = 8; // comma-separated competitor names string business_description = 9; // user's free-form business description string website_url = 10; string positioning_analysis = 11; string swot_analysis = 12; string channel_recommendations = 13; string content_strategy = 14; string competitive_landscape = 15; string ai_opinion = 16; // strategic opinion from the AI market-analyst string status = 17; // "pending", "generating", "completed", "error" map<string, string> metadata = 18; google.protobuf.Timestamp created_at = 19; google.protobuf.Timestamp updated_at = 20; // Structured breakdown of channel_recommendations/content_strategy above, // parsed via a schema-constrained LLM call (see GenerateStructured in // cmd/model_server.go) instead of left as free text for the client to // guess at. Populated by GenerateDiagnostic; empty on a freshly-created, // not-yet-generated Diagnostic. repeated ChannelPrescription channel_prescriptions = 21; repeated AudienceSegment audience_segments = 22; repeated CronogramTask cronogram = 23; // URLs/titles of the real sources (site, LinkedIn, web search results) // the AI actually grounded this diagnostic in — see internal/metasearch. repeated string sources_used = 24; // Real, backend-verified actions taken during generation (e.g. "Scraped // live content from acme.com"), same convention as StreamChunk.agent_tasks // — streamed live during GenerateDiagnostic and persisted here so the // trace survives after generation finishes, not just visible mid-stream. repeated string agent_tasks = 25; // User's selected goals for the diagnostic repeated string goals = 26; repeated DocumentPrescription document_prescriptions = 27; // Generative-Engine-Optimization insights — how to shape brand awareness / // discoverability in AI metasearch engines via lexical relevance, split out // from the audience-targeting prescriptions above. repeated BrandVisibilityInsight brand_visibility = 28; // Every verdict the judging ladder reached on this diagnostic's proposals // (channel prescriptions + brand-visibility insights), accepted AND // rejected, with the ladder's own counts. A dissented proposal appears // ONLY here (accepted=false), never in the lists above. Kept in PULSE's own // store with the structured analysis. Unset = not judged. runink.ui.judgement.v1.JudgementSet judgements = 29; } message CreateDiagnosticRequest { string business_name = 1; string industry = 2; string niche = 3; string target_audience = 4; string current_channels = 5; string competitors = 6; string business_description = 7; string website_url = 8; repeated string goals = 9; } message GetDiagnosticRequest { string id = 1; } message ListDiagnosticsRequest { PaginationRequest pagination = 1; } message ListDiagnosticsResponse { repeated Diagnostic diagnostics = 1; PaginationResponse pagination = 2; } message GenerateDiagnosticRequest { string diagnostic_id = 1; // ID of the pre-created diagnostic to populate } message UpdateDiagnosticRequest { string id = 1; string business_name = 2; string industry = 3; string niche = 4; string target_audience = 5; string current_channels = 6; string competitors = 7; string business_description = 8; string website_url = 9; map<string, string> metadata = 10; } message ExportDiagnosticPDFRequest { string diagnostic_id = 1; } message ExportDiagnosticPDFResponse { bytes pdf_data = 1; string filename = 2; } // ApplyAuditActionsRequest audits url and applies auto-fixable actions to the // repo at repo_path. mode ∈ {plan,apply,commit,pr}; empty = plan (dry-run). message ApplyAuditActionsRequest { string url = 1; string repo_path = 2; string profile = 3; string mode = 4; // plan|apply|commit|pr string branch = 5; // default: seo/pulse-remediation string base = 6; // default: main } // ApplyAuditActionsResponse reports the detected stack, the planned/applied file // changes, the manual (copy/infra) actions left for review, and the git result. message ApplyAuditActionsResponse { string stack = 1; double overall_score = 2; repeated PlannedChange changes = 3; repeated AuditAction manual = 4; ApplyGitResult git = 5; string pr_body = 6; } // PlannedChange is one file the agent would create/modify/skip. message PlannedChange { string path = 1; string op = 2; // create|modify|skip string check_id = 3; string reason = 4; } // ApplyGitResult reports how far the git/PR step got, with manual instructions // when credentials or gh are unavailable. message ApplyGitResult { string branch = 1; bool committed = 2; bool pushed = 3; string pr_url = 4; string instructions = 5; } // AuditAction is a concrete remediation fix-artifact for a check: the actual // content to apply (robots.txt, canonical tag, JSON-LD block, rewritten title, // header config) plus where it goes and whether it's safe to auto-apply. message AuditAction { string check_id = 1; string title = 2; string rationale = 3; string severity = 4; // critical|high|medium|low string type = 5; // file_create|head_insert|content_edit|header_config|manual string target_hint = 6; string artifact = 7; // the concrete content/sn